function populateLocalModels(models){
  let select=$('localmodel');
  let hiveSelect=$('hivemodel');
  if(!select)return;
  let previous=select.value;
  select.replaceChildren();
  (models||[]).forEach(name=>{
    let o=document.createElement('option');
    o.value=name;
    o.textContent=name;
    select.appendChild(o);
  });
  if(models?.includes(previous))select.value=previous;
  else if(models?.includes('qwen2.5-coder:14b'))select.value='qwen2.5-coder:14b';
  else if(models?.length)select.value=models[0];

  if(hiveSelect){
    let hp=hiveSelect.value;
    hiveSelect.replaceChildren();
    (models||[]).forEach(name=>{
      let o=document.createElement('option');
      o.value=name;o.textContent=name;hiveSelect.appendChild(o);
    });
    if(models?.includes(hp))hiveSelect.value=hp;
    else if(models?.includes('qwen2.5-coder:14b'))hiveSelect.value='qwen2.5-coder:14b';
    else if(models?.length)hiveSelect.value=models[0];
  }
}
