async function saveOllamaEndpoint(){
  let url=$('ollamaendpoint').value.trim();
  if(!url)return;
  try{
    let j=await api('/api/config/ollama-endpoint',{
      method:'POST',
      body:JSON.stringify({url})
    });
    $('localmodels').textContent=j.models?.length?'Detected: '+j.models.join(', '):'No Ollama models detected.';
    $('ollamaerror').textContent=j.error?('Discovery detail: '+j.error):'';
    populateLocalModels(j.models||[]);
    if(j.ok && j.models?.length){
      $('status').textContent=`LOCAL ✓ · ${($('status').textContent.includes('OPENAI ✓'))?'OPENAI ✓':'OPENAI —'}`;
    }
  }catch(e){
    $('ollamaerror').textContent='Connection error: '+e.message;
  }
}
